const sessionId = typeof $json.sessionId === 'string' ? $json.sessionId.trim() : '';
const brand = typeof $json.brand === 'string' ? $json.brand.trim().toLowerCase() : '';
const status = typeof $json.status === 'string' && $json.status.trim() !== ''
  ? $json.status.trim().toLowerCase()
  : 'all';
const listName = typeof $json.listName === 'string' ? $json.listName.trim() : '';
const proposedInput = { sessionId, brand, status, listName };
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const brandPattern = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const statuses = ['all', 'imported', 'needs_review', 'enriched', 'emailed', 'opened', 'followed_up', 'replied', 'closed'];
let error = null;

if (!uuidPattern.test(sessionId)) {
  error = { code: 'INVALID_SESSION', message: 'The prospect request needs a valid conversation session.' };
} else if (brand !== '' && (brand.length > 40 || !brandPattern.test(brand))) {
  error = { code: 'INVALID_BRAND', message: 'Brand must be a short lowercase identifier such as oddtoe or datalabs.' };
} else if (!statuses.includes(status)) {
  error = { code: 'INVALID_STATUS', message: `Status must be one of: ${statuses.join(', ')}.` };
} else if (listName.length > 120) {
  error = { code: 'INVALID_LIST', message: 'The list name must be 120 characters or fewer.' };
}

return {
  json: {
    valid: error === null,
    sessionId,
    brand,
    status,
    listName,
    proposedInput,
    ...(error ? { response: { ok: false, error } } : {})
  }
};

const input = $('Validate List Input').first().json;
const body = $json;
if (body?.schemaVersion !== 1 || !Array.isArray(body.prospects)) {
  return [{
    json: {
      ...input,
      response: {
        ok: false,
        error: {
          code: 'PROSPECT_DATA_UNAVAILABLE',
          message: 'The local prospect store is not available. Check the chat app is running, then try again.'
        }
      }
    }
  }];
}
const prospects = body.prospects.map((row) => ({
  company: row.company,
  listName: row.listName,
  brand: row.brand,
  rowNumber: row.rowNumber ?? null,
  region: row.region,
  tier: row.tier,
  website: row.website,
  linkedinCompanyUrl: row.linkedinCompanyUrl,
  contactName: row.contactName,
  contactEmail: row.contactEmail,
  linkedinUrl: row.linkedinUrl,
  confidence: row.confidence,
  flagReason: row.flagReason,
  status: row.status,
  notes: row.notes
}));
return [{
  json: {
    ...input,
    response: {
      ok: true,
      filters: { brand: input.brand || 'all', status: input.status, listName: input.listName || 'all' },
      summary: body.summary,
      count: prospects.length,
      prospects
    }
  }
}];

const response = $json.response;
const error = response?.ok === false ? String(response.error?.message ?? 'Tool failed') : '';
return {
  json: {
    occurredAt: new Date().toISOString(),
    sessionId: String($json.sessionId ?? ''),
    requestId: String(''),
    toolName: 'list_prospects',
    proposedInput: JSON.stringify($json.proposedInput ?? {}),
    result: JSON.stringify(response),
    error,
    response
  }
};

const prepared = $('Prepare Audit').item.json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) {
  response.auditWarning = 'The tool result could not be written to the local audit table.';
}
return { json: response };
